TriggerOraclev10g.body:
DECLARE
    V_COD_HOTEL HOTEL_GESTAO.TB_HOTEL.COD_HOTEL%TYPE;
BEGIN
    IF :NEW.COD_RESERVA IS NOT NULL THEN

        SELECT Q.COD_HOTEL
          INTO V_COD_HOTEL
          FROM HOTEL_GESTAO.TB_RESERVA R
          JOIN HOTEL_GESTAO.TB_QUARTO Q
            ON Q.COD_QUARTO = R.COD_QUARTO
         WHERE R.COD_RESERVA = :NEW.COD_RESERVA;

        IF V_COD_HOTEL <> :NEW.COD_HOTEL THEN
            RAISE_APPLICATION_ERROR(
                -20002,
                'A reserva informada pertence a outro hotel.'
            );
        END IF;

    END IF;
END;
